// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(c), 1 ether);
        address target = address(this);
        uint initial = c.depositsCount();
        vm.prank(c.owner());
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, 0.5 ether));
        uint finalCount = c.depositsCount();
        assertTrue(success == false && finalCount == initial);
    }
}
